codify_button_html = """
<style>
/* Make Streamlit buttons 3D */
[data-testid="baseButton-secondary"] {
    background: linear-gradient(180deg, rgba(0, 229, 255, 0.9) 0%, rgba(0, 150, 200, 0.8) 100%) !important;
    border-top: 2px solid #ffffff !important;
    border-bottom: 6px solid rgba(0, 50, 80, 0.9) !important;
    border-radius: 15px !important;
    box-shadow: 0 10px 20px rgba(0, 229, 255, 0.3), inset 0 -5px 15px rgba(0,0,0,0.3) !important;
    color: white !important;
    font-weight: bold;
    transform: perspective(500px) rotateX(5deg);
    transition: all 0.2s;
    position: relative;
    z-index: 10;
}

[data-testid="baseButton-secondary"]:active {
    transform: perspective(500px) rotateX(5deg) translateY(4px);
    border-bottom: 2px solid rgba(0, 50, 80, 0.9) !important;
    box-shadow: 0 2px 5px rgba(0, 229, 255, 0.2), inset 0 -2px 5px rgba(0,0,0,0.3) !important;
}

/* Animation of the mascot happily bobbing on the button */
@keyframes button-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-3px); }
}
</style>

<!-- Mascot overlay container that places it directly ON the button's center, legs dangling inward -->
<div style="position: relative; width: 100%; height: 0; z-index: 9999; pointer-events: none; display: flex; justify-content: center;">
<img src="data:image/png;base64," style="position: absolute; bottom: 0px; width: 100px; height: auto; transform-origin: bottom center; animation: button-bob 2s ease-in-out infinite; filter: drop-shadow(0 15px 10px rgba(0,0,0,0.6)); pointer-events: none;" />
</div>
"""
